// Reverse a string by looping from the last character to the first
const reverseString = (str) => {
  let reversed = "";

  // Start from the last character
  for (let i = str.length - 1; i >= 0; i--) {
    reversed += str[i];
  }

  return reversed;
};

console.log(reverseString("Jeet")); // "teeJ"

// Count the number of vowels in a string
const countVowels = (str) => {
  const vowels = "aeiouAEIOU";
  let count = 0;

  // Check every character in the string
  for (let i = 0; i < str.length; i++) {
    // Increase count if the character is a vowel
    if (vowels.includes(str[i])) {
      count++;
    }
  }

  return count;
};

console.log(countVowels("saheli")); // 3

// Check whether every character is a digit
const containsOnlyDigits = (str) => {
  // An empty string is not considered a valid number here
  if (str.length === 0) return false;

  for (const char of str) {
    // Check whether the character is outside the range 0 to 9
    if (char < "0" || char > "9") {
      return false;
    }
  }

  return true;
};

console.log(containsOnlyDigits("123456")); // true
console.log(containsOnlyDigits("12r1234")); // false

// Check whether a string reads the same forward and backward
const isPalindrome = (str) => {
  let reversed = "";

  // Reverse the string
  for (let i = str.length - 1; i >= 0; i--) {
    reversed += str[i];
  }

  // Compare the reversed string with the original string
  return reversed === str;
};

const result = isPalindrome("madam");

console.log(result ? "Palindrome" : "Not a Palindrome");

// Convert the first letter of every word to uppercase
const titleCase = (str) => {
  const words = str.split(" ");
  const result = [];

  for (const word of words) {
    // Capitalize the first character and lowercase the remaining characters
    const formattedWord =
      word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();

    result.push(formattedWord);
  }

  // Join all words back into a sentence
  return result.join(" ");
};

console.log(titleCase("hello WORLD")); // "Hello World"

// Find the word with the greatest length
const findLongestWord = (sentence) => {
  const words = sentence.split(" ");
  let longestWord = "";

  // Compare every word with the current longest word
  for (const word of words) {
    if (word.length > longestWord.length) {
      longestWord = word;
    }
  }

  return longestWord;
};

console.log(findLongestWord("I love JavaScript programming")); // "programming"

// Reverse the order of words in a sentence
const reverseWords = (sentence) => {
  const words = sentence.split(" ");
  const reversedWords = [];

  // Start from the last word
  for (let i = words.length - 1; i >= 0; i--) {
    reversedWords.push(words[i]);
  }

  return reversedWords.join(" ");
};

console.log(reverseWords("I love you Saheli"));
// "Saheli you love I"

// Remove duplicate characters while keeping the first occurrence
const removeDuplicateCharacters = (str) => {
  const seen = {};
  let result = "";

  for (const char of str) {
    // Add the character only if we have not seen it before
    if (!seen[char]) {
      seen[char] = true;
      result += char;
    }
  }

  return result;
};

console.log(removeDuplicateCharacters("abcad")); // "abcd"

// Find the character that appears the most times
const findMaxOccurringCharacter = (str) => {
  const frequency = {};
  let maxCharacter = "";
  let maxCount = 0;

  for (const char of str) {
    // Increase the frequency of the current character
    frequency[char] = (frequency[char] || 0) + 1;

    // Update the maximum when a higher frequency is found
    if (frequency[char] > maxCount) {
      maxCount = frequency[char];
      maxCharacter = char;
    }
  }

  return {
    character: maxCharacter,
    count: maxCount
  };
};

console.log(findMaxOccurringCharacter("javascript"));

// Check whether str2 is a rotation of str1
const isRotation = (str1, str2) => {
  // Rotations must have the same length
  if (str1.length !== str2.length) {
    return false;
  }

  // A rotation will always exist inside str1 + str1
  return (str1 + str1).includes(str2);
};

console.log(isRotation("abcd", "cdab")); // true
console.log(isRotation("abcd", "acbd")); // false

// Check whether two strings contain the same characters
const isAnagram = (str1, str2) => {
  // Strings with different lengths cannot be anagrams
  if (str1.length !== str2.length) {
    return false;
  }

  const frequency = {};

  // Count characters from the first string
  for (const char of str1) {
    frequency[char] = (frequency[char] || 0) + 1;
  }

  // Remove matching characters using the second string
  for (const char of str2) {
    if (!frequency[char]) {
      return false;
    }

    frequency[char]--;
  }

  return true;
};

console.log(isAnagram("listen", "silent")); // true
console.log(isAnagram("jeet", "paul")); // false

// Find the first character that appears only once
const firstNonRepeatingCharacter = (str) => {
  const frequency = {};

  // Count how many times each character appears
  for (const char of str) {
    frequency[char] = (frequency[char] || 0) + 1;
  }

  // Find the first character with frequency 1
  for (const char of str) {
    if (frequency[char] === 1) {
      return char;
    }
  }

  return null;
};

console.log(firstNonRepeatingCharacter("aabbcdde")); // "c"

// Compress consecutive repeating characters
const stringCompression = (str) => {
  if (str.length === 0) return "";

  let result = "";
  let count = 1;

  // Compare each character with the next character
  for (let i = 0; i < str.length - 1; i++) {
    if (str[i] === str[i + 1]) {
      count++;
    } else {
      // Add the character and its count when the sequence ends
      result += str[i] + count;
      count = 1;
    }
  }

  // Add the final character group
  result += str[str.length - 1] + count;

  return result;
};

console.log(stringCompression("aaabb")); // "a3b2"
console.log(stringCompression("aabbccddd")); // "a2b2c2d3"

// Generate every possible non-empty substring
const findAllSubstrings = (str) => {
  const result = [];

  // Choose the starting position
  for (let i = 0; i < str.length; i++) {
    // Choose the ending position
    for (let j = i + 1; j <= str.length; j++) {
      result.push(str.slice(i, j));
    }
  }

  return result;
};

console.log(findAllSubstrings("abc"));
// ["a", "ab", "abc", "b", "bc", "c"]

// Find the common prefix shared by all strings
const longestCommonPrefix = (strs) => {
  if (strs.length === 0) return "";

  // Start by assuming the first string is the prefix
  let prefix = strs[0];

  // Compare the prefix with every remaining string
  for (let i = 1; i < strs.length; i++) {
    // Keep removing characters until it becomes a prefix
    while (!strs[i].startsWith(prefix)) {
      prefix = prefix.slice(0, -1);

      // No common prefix exists
      if (prefix === "") {
        return "";
      }
    }
  }

  return prefix;
};

console.log(longestCommonPrefix(["flower", "flow", "flight"]));
// "fl"

// Check whether all brackets are correctly opened and closed
const isValidParentheses = (str) => {
  const stack = [];

  // Define which opening bracket matches each closing bracket
  const pairs = {
    ")": "(",
    "]": "[",
    "}": "{"
  };

  for (const char of str) {
    // Add opening brackets to the stack
    if (char === "(" || char === "[" || char === "{") {
      stack.push(char);
    } else if (pairs[char]) {
      // The latest opening bracket must match the closing bracket
      if (stack.pop() !== pairs[char]) {
        return false;
      }
    }
  }

  // The stack must be empty if every bracket was matched
  return stack.length === 0;
};

console.log(isValidParentheses("(){}[]")); // true
console.log(isValidParentheses("([)]")); // false

// Find the longest substring containing only unique characters
const longestSubstringWithoutRepeating = (str) => {
  const characters = new Set();

  let left = 0;
  let start = 0;
  let maxLength = 0;

  // Move the right pointer through the string
  for (let right = 0; right < str.length; right++) {
    // Remove characters from the left until the duplicate is removed
    while (characters.has(str[right])) {
      characters.delete(str[left]);
      left++;
    }

    // Add the current character to the window
    characters.add(str[right]);

    // Update the longest substring information
    if (right - left + 1 > maxLength) {
      maxLength = right - left + 1;
      start = left;
    }
  }

  return str.slice(start, start + maxLength);
};

console.log(longestSubstringWithoutRepeating("abcab"));
// "abc"
